"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

/**
 * MoneytreesLogo — the animated palm-tree mark.
 *
 * At rest: a palm on a coin mound. On hover: the canopy does a springy
 * little lift (--spring-bouncy) and bills + a coin tumble down from the
 * fronds in a staggered rain that loops while the pointer stays. All
 * colors ride theme tokens so the mark adapts to light/dark like any
 * other surface. Reduced motion renders the static mark only.
 */

const SPRING_BOUNCY = { type: "spring", stiffness: 520, damping: 18, mass: 0.6 } as const;

type MoneytreesLogoProps = {
  /** Rendered size in px (square). */
  size?: number;
  /** Wrap the mark in a liquid-glass tile. */
  tile?: boolean;
  /** Force the money rain on (e.g. for showcase/demo) instead of hover. */
  raining?: boolean;
  className?: string;
  title?: string;
};

type DropSpec = {
  kind: "bill" | "coin";
  x: number;
  fromY: number;
  drift: number;
  rotate: number;
  delay: number;
};

/* Three bills and a coin, released from under the canopy at staggered
 * offsets. Values are tuned so nothing exits the viewBox. */
const DROPS: DropSpec[] = [
  { kind: "bill", x: 17, fromY: 24, drift: -3, rotate: -24, delay: 0 },
  { kind: "coin", x: 48, fromY: 22, drift: 2, rotate: 0, delay: 0.18 },
  { kind: "bill", x: 30, fromY: 26, drift: 3, rotate: 18, delay: 0.34 },
  { kind: "bill", x: 41, fromY: 23, drift: -2, rotate: -14, delay: 0.52 },
];

function Bill() {
  return (
    <>
      <rect
        x={-4}
        y={-2.5}
        width={8}
        height={5}
        rx={1}
        fill="var(--color-bull)"
        stroke="var(--color-bull-foreground)"
        strokeOpacity={0.35}
        strokeWidth={0.5}
      />
      <circle
        r={1.4}
        fill="none"
        stroke="var(--color-bull-foreground)"
        strokeOpacity={0.7}
        strokeWidth={0.5}
      />
    </>
  );
}

function Coin() {
  return (
    <>
      <circle r={3} fill="var(--color-gold)" />
      <circle
        r={2}
        fill="none"
        stroke="var(--color-gold-foreground)"
        strokeOpacity={0.5}
        strokeWidth={0.5}
      />
    </>
  );
}

function FallingMoney({ active }: { active: boolean }) {
  return (
    <>
      {DROPS.map((d, i) => (
        <motion.g
          key={i}
          initial={false}
          animate={
            active
              ? {
                  y: [d.fromY, d.fromY + 30],
                  x: [d.x, d.x + d.drift],
                  rotate: [0, d.rotate],
                  opacity: [0, 1, 1, 0],
                }
              : { y: d.fromY, x: d.x, rotate: 0, opacity: 0 }
          }
          transition={
            active
              ? {
                  duration: 1.1,
                  delay: d.delay,
                  ease: "easeIn",
                  repeat: Infinity,
                  repeatDelay: 0.35,
                }
              : { duration: 0.15 }
          }
        >
          {d.kind === "bill" ? <Bill /> : <Coin />}
        </motion.g>
      ))}
    </>
  );
}

function PalmMark() {
  return (
    <>
      {/* Coin mound the palm grows from */}
      <ellipse cx={32} cy={57} rx={11} ry={3.5} fill="var(--color-gold-soft)" />
      <circle cx={27} cy={56} r={2.4} fill="var(--color-gold)" />
      <circle cx={33} cy={57} r={2.4} fill="var(--color-gold)" />
      <circle cx={38.5} cy={55.5} r={2.4} fill="var(--color-gold)" />
      {/* Trunk */}
      <path
        d="M31 56 C 30.5 46, 31 38, 34 27"
        fill="none"
        stroke="var(--color-bronze)"
        strokeWidth={3.4}
        strokeLinecap="round"
      />
      {/* Coconuts */}
      <circle cx={31.5} cy={27.5} r={2.2} fill="var(--color-gold)" />
      <circle cx={36.5} cy={28.5} r={2.2} fill="var(--color-gold)" />
    </>
  );
}

function Canopy() {
  return (
    <g fill="none" stroke="var(--color-bull)" strokeWidth={3} strokeLinecap="round">
      <path d="M34 26 Q 23 18, 13 22" />
      <path d="M34 26 Q 25 12, 16 11" />
      <path d="M34 26 Q 31 11, 25 7" />
      <path d="M34 26 Q 41 10, 49 9" />
      <path d="M34 26 Q 45 15, 53 19" />
    </g>
  );
}

export function MoneytreesLogo({
  size = 40,
  tile = false,
  raining = false,
  className,
  title = "moneytrees",
}: MoneytreesLogoProps) {
  const reduced = useReducedMotion();
  const [hovering, setHovering] = React.useState(false);
  const active = !reduced && (raining || hovering);

  const svg = reduced ? (
    <svg width={size} height={size} viewBox="0 0 64 64" role="img" aria-label={title}>
      <PalmMark />
      <Canopy />
    </svg>
  ) : (
    <motion.svg
      width={size}
      height={size}
      viewBox="0 0 64 64"
      role="img"
      aria-label={title}
      onHoverStart={() => setHovering(true)}
      onHoverEnd={() => setHovering(false)}
      style={{ overflow: "visible" }}
    >
      <FallingMoney active={active} />
      <PalmMark />
      <motion.g
        style={{ originX: "34px", originY: "27px" }}
        animate={active ? { scale: 1.06, rotate: -2 } : { scale: 1, rotate: 0 }}
        transition={SPRING_BOUNCY}
      >
        <Canopy />
      </motion.g>
    </motion.svg>
  );

  if (!tile) {
    return <span className={cn("inline-flex", className)}>{svg}</span>;
  }

  return (
    <span
      data-variant="card"
      className={cn(
        "mt-liquid-css inline-flex items-center justify-center rounded-bubble-sm p-1.5",
        className,
      )}
    >
      {svg}
    </span>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { MoneytreesLogo } from "./moneytrees-logo";
import { MoneytreesWordmark } from "./wordmark";

/**
 * MoneytreesLockup — horizontal icon + wordmark, the header-grade brand
 * unit. Hovering anywhere in the lockup makes it rain.
 */
export function MoneytreesLockup({
  size = 32,
  className,
}: {
  /** Icon size in px; the wordmark scales to match. */
  size?: number;
  className?: string;
}) {
  const [hovering, setHovering] = React.useState(false);
  return (
    <span
      className={cn("inline-flex items-center gap-2", className)}
      onPointerEnter={() => setHovering(true)}
      onPointerLeave={() => setHovering(false)}
    >
      <MoneytreesLogo size={size} raining={hovering} />
      <MoneytreesWordmark style={{ fontSize: size * 0.62 }} className="leading-none" />
    </span>
  );
}

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * MoneytreesWordmark — lowercase type-only mark. "money" rides the
 * foreground; "trees" takes the bull accent. Scale it with text-size
 * utilities (`text-xl`, `text-2xl`, …) via className.
 */
export function MoneytreesWordmark({
  className,
  style,
}: {
  className?: string;
  style?: React.CSSProperties;
}) {
  return (
    <span className={cn("font-sans font-bold lowercase tracking-tight", className)} style={style}>
      money<span className="text-[var(--color-bull-fg)]">trees</span>
    </span>
  );
}
